import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "./global.css";

export default function ProductPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);

  useEffect(() => {
    axios
      .get(`http://localhost:5001/api/products/${id}`)
      .then((res) => setProduct(res.data))
      .catch((err) => console.log(err));
  }, [id]);

  if (!product) return <h2 style={{ textAlign: "center" }}>Loading...</h2>;

  const startSwap = () => {
    // send this product as the one user wants to swap away
    navigate("/", { state: { swapFor: product } });
  };

  return (
    <div className="product-detail" style={{ padding: 30 }}>
      <div className="product-image-section">
        <img src={product.image} alt={product.title} style={{ width: 480, maxWidth: "100%", borderRadius: 12 }} />
      </div>

      <div className="product-detail-info">
        <h1>{product.title}</h1>

        <p style={{ fontSize: 20, color: "#1aaf5d", fontWeight: 700 }}>₹{product.price}</p>
        <p style={{ fontSize: 16 }}>Size: {product.size}</p>
        <p style={{ marginTop: 18 }}>{product.description}</p>

        <div style={{ display: "flex", gap: 12, marginTop: 20 }}>
          <button className="buy-btn" onClick={() => alert("Buy flow not implemented")}>Buy Now</button>

          <button className="swap-btn" onClick={startSwap}>Swap</button>
        </div>
      </div>
    </div>
  );
}
